int tally = 0;
void countA(String tower) {
    if (tower.isEmpty()) {
        return;
    }
    tally = tally + 1;
    countA(tower.substring(1));
}

// Variant B
int countB(String tower, int tally) {
    if (tower.isEmpty()) {
        return tally;
    }
    return countB(tower.substring(1), tally + 1);
}

// Variant C
int countC(String tower) {
    if (tower.isEmpty()) {
        return 0;
    }
    return 1 + countC(tower.substring(1));
}
